/*
 * bst.h -- CS 313 P3: binary search tree with parent pointers.
 *
 * DO NOT EDIT THIS FILE. The autograder uses its own copy.
 *
 * Contracts (see README.md):
 *   - Keys are ints. Duplicates are allowed and go RIGHT (as in CLRS):
 *     when inserting key k at node x, go left if k < x->key, else right.
 *   - Operations that can fail return bool and pass their result through
 *     an out-parameter. They never exit, print, or crash on an empty tree
 *     or a missing key.
 *   - bst_find and every "find a key" step use the first match on the
 *     search path from the root (the copy closest to the root).
 */
#ifndef BST_H
#define BST_H

#include <stdbool.h>

typedef struct bst_node {
    int key;
    struct bst_node *left;
    struct bst_node *right;
    struct bst_node *parent;   /* NULL for the root */
} bst_node;

typedef struct {
    bst_node *root;            /* NULL when the tree is empty */
} bst;

/* Allocate and return a new empty tree. (Provided.) */
bst *bst_create(void);

/* Free every node and then the tree itself. t may be NULL. */
void bst_destroy(bst *t);

/* Insert key as a new leaf (duplicates go right). */
void bst_insert(bst *t, int key);

/* Return the node holding key (closest to the root), or NULL if absent. */
bst_node *bst_find(const bst *t, int key);

/* Return true if key is in the tree. */
bool bst_contains(const bst *t, int key);

/* Smallest / largest key. Return false (and leave *out alone) if empty. */
bool bst_min(const bst *t, int *out);
bool bst_max(const bst *t, int *out);

/*
 * Successor of key: the key that follows bst_find(t, key) in an inorder
 * walk. Return false (and leave *out alone) if key is not in the tree or
 * if that node has no successor (it is the last node in an inorder walk).
 * A duplicated maximum has a successor: in a tree of 5 and 5, the
 * successor of 5 is the other 5.
 */
bool bst_successor(const bst *t, int key, int *out);

/*
 * CLRS TRANSPLANT: replace the subtree rooted at u with the subtree rooted
 * at v (v may be NULL). Updates u's parent (or t->root) and v->parent.
 * Does not touch u->left, u->right, or free anything.
 * Declared here so the tests can call it directly.
 */
void bst_transplant(bst *t, bst_node *u, bst_node *v);

/*
 * Delete one copy of key (the node bst_find returns) using the CLRS
 * TRANSPLANT-based algorithm; a node with two children is replaced by its
 * successor. Frees the removed node. Return false, and leave the tree
 * unchanged, if key is not in the tree.
 */
bool bst_delete(bst *t, int key);

/*
 * Traversals. Write the keys in the given order into out[0..n-1] and
 * return n (the number of nodes). out must have room for bst_size(t) ints.
 * An empty tree returns 0 and writes nothing.
 */
int bst_preorder(const bst *t, int out[]);
int bst_inorder(const bst *t, int out[]);
int bst_postorder(const bst *t, int out[]);

/* Number of nodes. Empty tree: 0. */
int bst_size(const bst *t);

/* Height = edges on the longest root-to-leaf path. One node: 0. Empty: -1. */
int bst_height(const bst *t);

/* Print the tree sideways (root at left) for debugging. (Provided.) */
void bst_print(const bst *t);

#endif
